def resumen(xs):
    return {'media': sum(xs)/len(xs), 'maximo': max(xs)}
r = resumen([2, 4, 6])
print(r['media'])

def predice(x):
    return 1 if x >= 0 else 0
print(predice(2), predice(-1))

import numpy as np
def sigmoid(z):
    return 1 / (1 + np.exp(-z))
p = sigmoid(np.array([0., 2., -2.]))
print(round(p[0], 1))
